"""Run once before yieldcrest_model.py to build the synthetic demo database."""
from pathlib import Path
import sqlite3

if __name__ == "__main__":
    path = Path(__file__).with_name("yieldcrest_step2.sqlite")
    if path.exists():
        raise SystemExit("Database already exists.")
    with sqlite3.connect(path) as db:
        db.executescript('BEGIN TRANSACTION;\nCREATE TABLE eligible_faces(request_id INTEGER REFERENCES requests NOT NULL,face_id INTEGER REFERENCES faces NOT NULL,PRIMARY KEY(request_id,face_id));\nINSERT INTO "eligible_faces" VALUES(1,1);\nINSERT INTO "eligible_faces" VALUES(1,2);\nINSERT INTO "eligible_faces" VALUES(2,2);\nCREATE TABLE faces(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);\nINSERT INTO "faces" VALUES(1,\'Ameerpet\');\nINSERT INTO "faces" VALUES(2,\'Dilsukhnagar\');\nCREATE TABLE requests(id INTEGER PRIMARY KEY, client TEXT NOT NULL, start_day INTEGER NOT NULL, duration_days INTEGER NOT NULL CHECK(duration_days>0), net_rupees INTEGER NOT NULL, hold_days INTEGER NOT NULL, close_probability REAL NOT NULL CHECK(close_probability BETWEEN 0 AND 1));\nINSERT INTO "requests" VALUES(1,\'Agency\',7,15,30000,3,0.8);\nINSERT INTO "requests" VALUES(2,\'Retailer\',7,15,28000,0,1.0);\nCREATE TABLE vacancy_episodes(id INTEGER PRIMARY KEY,face_id INTEGER REFERENCES faces NOT NULL,arrival_day INTEGER,booked_days INTEGER NOT NULL,net_daily_rupees INTEGER NOT NULL);\nINSERT INTO "vacancy_episodes" VALUES(1,1,1,15,3000);\nINSERT INTO "vacancy_episodes" VALUES(2,1,2,10,3000);\nINSERT INTO "vacancy_episodes" VALUES(3,1,3,15,3000);\nINSERT INTO "vacancy_episodes" VALUES(4,1,4,10,3000);\nINSERT INTO "vacancy_episodes" VALUES(5,1,5,15,3000);\nINSERT INTO "vacancy_episodes" VALUES(6,1,6,10,3000);\nINSERT INTO "vacancy_episodes" VALUES(7,1,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(8,1,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(9,1,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(10,1,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(11,2,2,15,1800);\nINSERT INTO "vacancy_episodes" VALUES(12,2,3,10,1800);\nINSERT INTO "vacancy_episodes" VALUES(13,2,5,15,1800);\nINSERT INTO "vacancy_episodes" VALUES(14,2,6,10,1800);\nINSERT INTO "vacancy_episodes" VALUES(15,2,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(16,2,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(17,2,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(18,2,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(19,2,NULL,0,0);\nINSERT INTO "vacancy_episodes" VALUES(20,2,NULL,0,0);\nCOMMIT;')
